// Ã¢â€â‚¬Ã¢â€â‚¬ Debug log (shared file) Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
static void HLog(const char* fmt, ...) {
    char msg[1024];
    va_list ap; va_start(ap, fmt);
    _vsnprintf_s(msg, sizeof(msg), _TRUNCATE, fmt, ap);
    va_end(ap);
    SYSTEMTIME st; GetLocalTime(&st);
    char line[1200];
    int n = _snprintf_s(line, sizeof(line), _TRUNCATE, "[%02d:%02d:%02d.%03d] HOOK %s\r\n",
        st.wHour, st.wMinute, st.wSecond, st.wMilliseconds, msg);
    char path[MAX_PATH];
    if (!GetTempPathA(MAX_PATH, path)) return;
    strcat_s(path, MAX_PATH, "drape_debug.log");
    HANDLE h = CreateFileA(path, FILE_APPEND_DATA, FILE_SHARE_READ | FILE_SHARE_WRITE,
                           nullptr, OPEN_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (h == INVALID_HANDLE_VALUE) return;
    SetFilePointer(h, 0, nullptr, FILE_END);
    DWORD w; WriteFile(h, line, (DWORD)n, &w, nullptr); CloseHandle(h);
}

// Ã¢â€â‚¬Ã¢â€â‚¬ Hooked function signatures Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
static std::string SafeFilePart(const std::string& s) {
    std::string out;
    out.reserve(s.size());
    for (unsigned char ch : s) {
        if (std::isalnum(ch) || ch == '-' || ch == '_' || ch == '.')
            out.push_back((char)ch);
        else
            out.push_back('_');
    }
    if (out.empty())
        out = "unnamed";
    if (out.size() > 80)
        out.resize(80);
    return out;
}

static fs::path TempDrapePath(const std::string& fileName) {
    char path[MAX_PATH] = {};
    if (!GetTempPathA(MAX_PATH, path))
        return fs::path(fileName);
    return fs::path(path) / fileName;
}

// GAINED AN ARGUMENT IN 5.8.2: a trailing `const std::string& resultTargetName`.
// Declared here with the WIDER signature and always forwarded, which is correct
// for both hosts under the x64 convention: the CALLER owns the argument space,
// so handing an 11th argument to the 10-argument 5.6.3 build is simply ignored
// by it, while the 5.8.2 build receives the one it needs. The reverse -
// declaring ten and being called by a host that passes eleven - is what would
// misread the stack, so the wide form is the safe default rather than a
// per-version switch. On 5.6.3 the extra pointer we receive is meaningless and
// is never dereferenced; it is only handed straight back.
typedef void (*PfnGenResult)(
    void* self,
    const std::string* shapeName,
    const std::string* sliderName,
    const std::string* refDataName,
    bool transformResults, int maxResults, bool noSqueeze, bool solidMode,
    bool axisX, bool axisY, bool axisZ,
    const std::string* resultTargetName);

// DiffDataSets::ZeroVertDiff(set, target, vertSet, mask) Ã¢â‚¬â€ scales each diff
// vertex by mask[vert]; erases verts with weight 0 or absent from mask.
typedef void (*PfnDiffZeroVert)(
    void* diffDataSets,
    const std::string* set,
    const std::string* target,
    void* vertSet,   // std::vector<uint16_t>*  (we pass nullptr)
    void* mask);     // std::unordered_map<uint16_t,float>*

typedef TargetDataDiffs* (*PfnDiffGetDiffSet)(
    void* diffDataSets,
    const std::string* targetDataName);

// Automorph host methods. These are safer than dereferencing resultDiffData
// directly because the host owns the DiffDataSets internals and all STL nodes.
typedef void (*PfnGetRawResultDiff)(
    void* self,
    const std::string* shapeName,
    const std::string* sliderName,
    TargetDataDiffs* outDiff);

typedef void (*PfnSetResultDiff)(
    void* self,
    const std::string* shapeName,
    const std::string* sliderName,
    const TargetDataDiffs* diff);

static PfnGenResult        g_origGenResult     = nullptr;
static PfnDiffZeroVert     g_diffZeroVert      = nullptr;

